create type public.video_status as enum ('draft','published','archived');
create type public.enquiry_status as enum ('new','read','replied','archived','spam');
create table public.admin_users (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'admin' check (role in ('admin','editor')), created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, display_order integer not null default 0, is_visible boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.videos (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, short_description text, description text, youtube_url text not null, youtube_video_id text not null check (youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'), youtube_embed_url text not null, youtube_thumbnail_url text, custom_poster_url text, mobile_poster_url text, orientation text not null check (orientation in ('portrait','landscape')), aspect_ratio numeric not null, display_mode text not null default 'cover' check (display_mode in ('cover','contain')), focal_x numeric default .5 check (focal_x between 0 and 1), focal_y numeric default .5 check (focal_y between 0 and 1), category_id uuid references public.categories(id) on delete set null, tags text[] not null default '{}', client_name text, creative_role text, director text, production_company text, year integer, location text, credits jsonb not null default '[]', external_project_url text, featured boolean not null default false, display_order integer not null default 0, status public.video_status not null default 'draft', published_at timestamptz, seo_title text, seo_description text, og_image_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.enquiries (id uuid primary key default gen_random_uuid(), name text not null, email text not null, phone text, company text, project_type text, budget text, timeline text, message text not null, source_page text, referrer text, utm_source text, utm_medium text, utm_campaign text, status public.enquiry_status not null default 'new', internal_notes text, notification_status text not null default 'pending', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_content (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table public.site_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table public.activity_logs (id bigint generated always as identity primary key, actor_id uuid references auth.users(id) on delete set null, action text not null, entity_type text, entity_id text, created_at timestamptz not null default now());
create index videos_public_order_idx on public.videos(status, display_order) where status = 'published'; create index enquiries_status_idx on public.enquiries(status, created_at desc);
alter table public.admin_users enable row level security; alter table public.categories enable row level security; alter table public.videos enable row level security; alter table public.enquiries enable row level security; alter table public.site_content enable row level security; alter table public.site_settings enable row level security; alter table public.activity_logs enable row level security;
create policy "public published videos" on public.videos for select using (status = 'published'); create policy "public categories" on public.categories for select using (is_visible = true); create policy "public content" on public.site_content for select using (true); create policy "public settings" on public.site_settings for select using (true);
create policy "admins manage all" on public.videos for all using (exists(select 1 from public.admin_users where id = auth.uid())) with check (exists(select 1 from public.admin_users where id = auth.uid()));
create policy "admins manage categories" on public.categories for all using (exists(select 1 from public.admin_users where id = auth.uid())) with check (exists(select 1 from public.admin_users where id = auth.uid()));
create policy "admins manage enquiries" on public.enquiries for all using (exists(select 1 from public.admin_users where id = auth.uid())) with check (exists(select 1 from public.admin_users where id = auth.uid()));
create policy "admins manage content" on public.site_content for all using (exists(select 1 from public.admin_users where id = auth.uid())) with check (exists(select 1 from public.admin_users where id = auth.uid()));
create policy "admins manage settings" on public.site_settings for all using (exists(select 1 from public.admin_users where id = auth.uid())) with check (exists(select 1 from public.admin_users where id = auth.uid()));
create policy "admins read logs" on public.activity_logs for select using (exists(select 1 from public.admin_users where id = auth.uid()));
